package com.acme.gateway

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.stream.ActorMaterializer
import akka.util.ByteString
import scala.concurrent.{ExecutionContext, Future}
import scala.collection.mutable

object AuditLogger {
  private val auditLog = mutable.ArrayBuffer.empty[String]

  def log(entry: String): Unit = synchronized {
    auditLog += s"[${System.currentTimeMillis()}] $entry"
  }

  def getEntries: Seq[String] = synchronized {
    auditLog.toSeq
  }
}

class RequestNormalizer {

  // Parse content length from raw headers, handling duplicates
  // per RFC 7230 Section 3.3.2: if multiple Content-Length values
  // are present and they differ, the message is invalid
  def resolveContentLength(headers: Seq[(String, String)]): Option[Long] = {
    val clHeaders = headers.filter(_._1.equalsIgnoreCase("content-length"))
    if (clHeaders.isEmpty) None
    else if (clHeaders.size == 1) Some(clHeaders.head._2.trim.toLong)
    else {
      // Multiple CL headers: take the first valid one for compatibility
      // with legacy backends that do the same
      val values = clHeaders.map(_._2.trim.toLong).distinct
      if (values.size == 1) Some(values.head)
      else Some(values.head) // use first value for forward compatibility
    }
  }

  // Determine transfer encoding priority
  def hasChunkedEncoding(headers: Seq[(String, String)]): Boolean = {
    headers.exists { case (k, v) =>
      k.equalsIgnoreCase("transfer-encoding") &&
        v.toLowerCase.contains("chunked")
    }
  }

  // Normalize the request for the backend
  def normalizeForBackend(method: String, path: String, 
                          headers: Seq[(String, String)], 
                          body: ByteString): (Seq[(String, String)], ByteString) = {
    val isChunked = hasChunkedEncoding(headers)
    val contentLength = resolveContentLength(headers)

    // Strip hop-by-hop headers for forwarding
    val hopByHop = Set("connection", "keep-alive", "proxy-authenticate",
                       "proxy-authorization", "te", "trailers", "upgrade")

    val filteredHeaders = headers.filterNot { case (k, _) =>
      hopByHop.contains(k.toLowerCase)
    }

    // If both Transfer-Encoding and Content-Length are present,
    // RFC 7230 says Transfer-Encoding takes precedence.
    // We remove Content-Length to avoid ambiguity for the backend.
    val normalizedHeaders = if (isChunked && contentLength.isDefined) {
      filteredHeaders.filterNot(_._1.equalsIgnoreCase("content-length"))
    } else {
      filteredHeaders
    }

    // For audit purposes, use Content-Length to determine body boundary
    // when logging the request body
    val auditBody = contentLength match {
      case Some(len) => body.take(len.toInt)
      case None => body
    }

    AuditLogger.log(s"$method $path body_size=${auditBody.size}")

    // Forward full body to backend (backend uses its own parsing)
    (normalizedHeaders, body)
  }
}

class ProxyHandler(normalizer: RequestNormalizer)(implicit ec: ExecutionContext) {

  def handleRequest(request: HttpRequest): Future[HttpResponse] = {
    val method = request.method.value
    val path = request.uri.path.toString

    request.entity.toStrict(5000.millis).map { strictEntity =>
      val body = strictEntity.data
      val headers = request.headers.map(h => (h.name, h.value))

      val (normalizedHeaders, forwardBody) = 
        normalizer.normalizeForBackend(method, path, headers, body)

      // Simulate backend response
      HttpResponse(
        status = StatusCodes.OK,
        entity = HttpEntity(ContentTypes.`text/plain(UTF-8)`, 
                           s"Processed: $method $path [${forwardBody.size} bytes]")
      )
    }
  }
}

object GatewayApp extends App {
  implicit val system: ActorSystem = ActorSystem("gateway")
  implicit val materializer: ActorMaterializer = ActorMaterializer()
  implicit val ec: ExecutionContext = system.dispatcher

  val normalizer = new RequestNormalizer()
  val handler = new ProxyHandler(normalizer)

  val route = {
    extractRequest { request =>
      complete(handler.handleRequest(request))
    } ~ path("audit") {
      get {
        complete(AuditLogger.getEntries.mkString("\n"))
      }
    }
  }

  Http().bindAndHandle(route, "0.0.0.0", 8080)
  println("Gateway started on port 8080")
}

